/** prototype.html の <style> の中身。1文字も変えない。 */
export const APP_CSS = "  /* ===== 見た目の約束（2026-10-06 刷新・アプリ化要件定義.md F3-1「見た目（v15）」） =====\n     「生成りと藍」。信頼は藍、暖かみは生成りと杏、気軽さは丸い形と話し言葉でつくる。\n     流行りの効果（面のグラデーション・ガラス風・強い影・英字の飾り見出し）は使わない。 */\n  :root{\n    --bg:#F6F1E9; --surface:#FFFDF9; --sunken:#EFE8DC; --ink:#2B2724; --muted:#5F574F; --faint:#756C63;\n    --line:#E3DACB; --line-strong:#CFC3B0;\n    /* 主役のボタンとリンク（1画面に1つ）。診断そのものの色。 */\n    --chrome:#2D4A6B; --chrome-hover:#22395A;\n    --ai:#2D4A6B; --ai-soft:#E8EDF3; --trust:#2D4A6B;\n    /* 杏：進み具合・目印・帯。文字に使うときは杏・文字を使う。 */\n    --an:#E9A24C; --an-soft:#FBEBD2; --an-ink:#8A5A1F; --an-mark:#F8DDB0;\n    /* 夜の藍：深層の帯。ページで唯一の暗い面。 */\n    --night:#22303F; --night-sub:#C8D3E0; --night-faint:#A9B6C6;\n    /* coral/teal はタイプの極（open/guard）だけを表す。ほかの意味では使わない。 */\n    --coral:#C0492B; --coral-soft:#FBEDE7; --coral-ink:#7A2E1A;\n    --teal:#0F6E56; --teal-soft:#E3F1EB; --teal-ink:#0A4A3A;\n    --display:\"Noto Sans JP\",sans-serif; --body:\"Noto Sans JP\",sans-serif;\n    /* 読み解きガイド（本の体裁）専用。本文を明朝にすることで「読み物」に切り替える。 */\n    --serif:\"Noto Serif JP\",serif;\n    --shadow:0 1px 2px rgba(43,39,36,.04),0 10px 28px rgba(43,39,36,.06);\n    --radius:16px; --gutter:20px;\n    /* 4段階の回答。思わない側は鈍色、そう思う側は藍。タイプの極の色とは混ぜない。 */\n    --sc-no:#9A8C7B; --sc-yes:#2D4A6B;\n    /* タイプの極ごとのアクセント。結果画面とガイドで使う。 */\n    --accent:var(--coral); --accent-soft:var(--coral-soft); --accent-ink:var(--coral-ink);\n  }\n  .pole-guard{--accent:var(--teal); --accent-soft:var(--teal-soft); --accent-ink:var(--teal-ink)}\n  *{box-sizing:border-box;margin:0;padding:0}\n  /* display を持つクラス（.bk-next 等）に hidden 属性が負けないようにする */\n  [hidden]{display:none !important}\n  html{-webkit-text-size-adjust:100%}\n  body{\n    font-family:var(--body); color:var(--ink); background:var(--bg);\n    line-height:1.85; letter-spacing:.02em;\n    min-height:100vh; display:flex; align-items:flex-start; justify-content:center;\n    padding:0 var(--gutter) 48px;\n  }\n  a{color:var(--ai); text-underline-offset:4px}\n  a:hover{color:var(--chrome-hover)}\n  .app{width:100%; max-width:640px}\n  .screen{display:none; animation:fade .5s ease both}\n  .screen.active{display:block}\n  @keyframes fade{from{opacity:0; transform:translateY(8px)} to{opacity:1; transform:none}}\n  @media (prefers-reduced-motion:reduce){.screen,.screen.active{animation:none} *{transition:none!important}}\n\n  /* ===== ヘッダー（全画面共通）：ロゴ＋診断名。右側は画面ごとに出し分ける ===== */\n  .app-header{\n    display:flex; align-items:center; justify-content:space-between; gap:12px;\n    min-height:60px; margin-bottom:8px;\n  }\n  .brand{display:flex; align-items:center; gap:8px; min-height:44px; color:var(--ink); text-decoration:none}\n  .brand:hover{color:var(--ink)}\n  .brand-mark{display:block; width:30px; height:22px; flex:none}\n  .brand-name{font-family:var(--display); font-weight:700; font-size:18px; letter-spacing:.06em; line-height:1}\n  .head-nav{display:flex; align-items:center; gap:4px 24px}\n  .head-link{display:flex; align-items:center; min-height:44px; font-size:14px; font-weight:500; color:var(--ai)}\n  .head-pc{display:none}\n  .head-cta{\n    align-items:center; justify-content:center; font-family:var(--body); font-size:15px; font-weight:700; color:#fff; background:var(--chrome);\n    border:none; border-radius:99px; height:44px; padding:0 20px; cursor:pointer;\n  }\n  .head-cta:hover{background:var(--chrome-hover)}\n  /* 件数は設問のときだけ。トップのリンクはトップのときだけ。 */\n  .app-header .qcount{display:none}\n  .app:has(#quiz.active) .app-header .qcount{display:block}\n  .app:has(#intro:not(.active)) .head-nav{display:none}\n\n  /* ===== 文字と部品 ===== */\n  .eyebrow{font-size:13px; letter-spacing:.16em; font-weight:700; color:var(--ai); margin-bottom:8px; line-height:1.6}\n  /* <br> で改行位置を持たせた見出しは、行の途中では折らない（iPhone でも同じ折り方にする）。\n     収まらないときだけ、どこでも折れるようにして横にはみ出さない。 */\n  .hero{\n    font-family:var(--display); font-weight:700; line-height:1.45;\n    font-size:clamp(24px,6.6vw,30px); letter-spacing:.02em; margin-bottom:16px;\n  }\n  .hero:has(br),.top-h:has(br){word-break:keep-all; overflow-wrap:anywhere}\n  .lead{font-size:16px; color:var(--muted); margin-bottom:14px; max-width:34em}\n  @media (max-width:640px){ .lead-br{display:none} }\n  .mark{background:linear-gradient(transparent 62%, var(--an-mark) 62%)}\n  .btn{\n    display:inline-flex; align-items:center; justify-content:center; gap:10px; text-decoration:none;\n    font-family:var(--body); font-size:17px; font-weight:700; cursor:pointer; text-align:center;\n    color:#fff; background:var(--chrome); border:none; border-radius:99px;\n    min-height:58px; padding:14px 32px; line-height:1.5; letter-spacing:.06em;\n    box-shadow:0 6px 16px rgba(45,74,107,.22);\n    transition:background .2s, transform .1s;\n  }\n  .btn:hover{background:var(--chrome-hover); color:#fff}\n  .btn:active{transform:translateY(1px)}\n  .btn:focus-visible{outline:3px solid var(--an); outline-offset:3px}\n  .btn svg{width:20px; height:20px; flex:none}\n  .btn-wide{width:100%}\n  .btn:disabled{cursor:default; opacity:.6}\n  .btn.is-loading{position:relative; color:transparent !important; pointer-events:none; opacity:1}\n  .btn.is-loading::after{\n    content:\"\"; position:absolute; top:50%; left:50%; width:18px; height:18px; margin:-9px 0 0 -9px;\n    border:2.5px solid rgba(255,255,255,.45); border-top-color:#fff; border-radius:50%;\n    animation:btnspin .7s linear infinite;\n  }\n  @keyframes btnspin{to{transform:rotate(360deg)}}\n  @media (prefers-reduced-motion:reduce){ .btn.is-loading::after{animation:btnpulse 1.1s ease-in-out infinite} }\n  @keyframes btnpulse{0%,100%{opacity:.35} 50%{opacity:1}}\n  .btn-accent{color:#fff; background:var(--accent); box-shadow:none}\n  .btn-accent:hover{background:var(--accent); filter:brightness(.94)}\n  /* ふつうのボタン：枠だけ。主役のボタン（藍）と並べても主従が崩れない。 */\n  .btn-ghost{background:var(--surface); color:var(--ink); border:1.5px solid var(--line-strong); box-shadow:none}\n  .btn-ghost:hover{background:var(--surface); color:var(--ink); border-color:var(--ai)}\n  .btn-sm{font-size:15px; min-height:48px; padding:10px 22px; letter-spacing:.04em}\n  /* 文字のリンク（「詳しく見る」など）。右に小さな山形を添える。 */\n  .more-link{display:inline-flex; align-items:center; gap:6px; min-height:44px; font-size:15px; font-weight:500; color:var(--ai)}\n  .more-link::after{content:\"\"; width:7px; height:7px; border-top:2px solid currentColor; border-right:2px solid currentColor; transform:rotate(45deg); margin-left:2px}\n  /* 中央揃えの短い文だけ、行の長さを揃える */\n  .qhint{text-wrap:balance}\n  /* 文節の切れ目（<wbr>）でだけ折る。収まらないときだけ、どこでも折って横にはみ出さない。\n     アプリは抽出ツールが BudouX で <wbr> を入れたものを使う（app/tools/extract-content.mjs） */\n  .qtext,.choice,.qframe,.tname,.tt-name,.tl-name,.bk-title,.step-t,.pains li{word-break:keep-all; overflow-wrap:anywhere}\n\n  /* ===== トップ ===== */\n  .top-hero{padding-top:4px}\n  .top-hero .hero{margin:12px 0 0}\n  .top-hero .lead{margin:16px 0 0}\n  .top-hero .btn{margin-top:28px}\n  .cta-note{margin-top:12px; text-align:center; font-size:13px; color:var(--faint); line-height:1.7}\n  .top-hero-art{display:none}\n  .top-sec{margin-top:56px}\n  .top-h{font-family:var(--display); font-weight:700; font-size:clamp(19px,5.6vw,22px); line-height:1.5; letter-spacing:.02em}\n  .top-p{margin-top:16px; font-size:15px; color:var(--muted)}\n  .top-h + .top-p{margin-top:6px}\n  .top-empathy .top-p{margin-top:20px}\n  .pains{list-style:none; margin-top:20px; display:flex; flex-direction:column; gap:10px}\n  .pains li{\n    position:relative; padding:14px 16px 14px 48px; font-size:15px; line-height:1.7;\n    background:var(--surface); border:1px solid var(--line); border-radius:14px;\n  }\n  .pains li::before{content:\"\"; position:absolute; left:16px; top:17px; width:20px; height:20px; border-radius:50%; background:var(--an-soft)}\n  .pains li::after{content:\"\"; position:absolute; left:23px; top:21px; width:5px; height:9px; border-right:2px solid var(--an-ink); border-bottom:2px solid var(--an-ink); transform:rotate(45deg)}\n  .steps{\n    list-style:none; margin-top:20px; padding:20px; display:flex; flex-direction:column; gap:20px;\n    background:var(--surface); border:1px solid var(--line); border-radius:20px;\n  }\n  .step{display:flex; gap:14px; align-items:flex-start}\n  .step-no{\n    flex:none; width:36px; height:36px; border-radius:50%;\n    background:var(--ai-soft); color:var(--ai);\n    font-weight:700; font-size:16px; display:flex; align-items:center; justify-content:center;\n  }\n  .step-t{margin:4px 0 0; font-weight:700; font-size:16px; color:var(--ink); line-height:1.6}\n  .step-d{margin:4px 0 0; font-size:14px; color:var(--muted); line-height:1.75}\n  .type-grid{margin-top:16px; display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:10px}\n  .type-tile{\n    display:flex; flex-direction:column; align-items:flex-start; gap:6px; padding:12px;\n    background:var(--surface); border:1px solid var(--line); border-radius:14px;\n    color:var(--ink); text-decoration:none;\n  }\n  .type-tile:hover{color:var(--ink); border-color:var(--line-strong)}\n  .tt-code{padding:1px 8px; border-radius:99px; background:var(--coral); color:#fff; font-size:12px; font-weight:700; letter-spacing:.1em; line-height:1.6}\n  .type-tile.is-guard .tt-code{background:var(--teal)}\n  .tt-name{font-weight:700; font-size:14px; line-height:1.5}\n  .tt-catch{display:none}\n  .top-types .more-link{margin-top:12px}\n  .trust-list{\n    list-style:none; margin-top:20px; padding:20px; display:flex; flex-direction:column; gap:18px;\n    background:var(--surface); border:1px solid var(--line); border-radius:20px;\n  }\n  .trust-item{display:flex; gap:12px}\n  .trust-ico{flex:none; width:32px; height:32px; border-radius:50%; background:var(--ai-soft); color:var(--ai); display:flex; align-items:center; justify-content:center}\n  .trust-ico svg{width:18px; height:18px}\n  .trust-t{margin-top:2px; font-weight:700; font-size:15px; line-height:1.6}\n  .trust-d{margin-top:4px; font-size:14px; line-height:1.75; color:var(--muted)}\n  .trust-list + .more-link{margin-top:12px}\n  .top-band{margin-top:48px; padding:28px 20px; border-radius:24px; background:var(--an-soft); text-align:center}\n  .band-art{display:block; width:56px; height:40px; margin:0 auto 12px}\n  .top-band .top-p{margin-top:10px}\n  .top-band .btn{margin-top:20px}\n\n  /* ===== はじめに ===== */\n  #frame{position:relative}\n  #frame > *:not(.frame-art){position:relative}\n  /* 背景の2つの円。読む邪魔をしないよう、ごく薄く敷く。右端で切れるよう枠で切り抜く。 */\n  .frame-art{position:absolute; top:-28px; right:calc(-1 * var(--gutter)); width:260px; height:186px; overflow:hidden; opacity:.12; pointer-events:none}\n  .frame-art svg{display:block; width:320px; height:229px}\n  .frame-title{margin-top:0}\n  .frame-why{font-size:15px; line-height:1.85; color:var(--muted); background:var(--surface); border:1px solid var(--line); border-radius:20px; padding:20px; margin:20px 0}\n  .tips{list-style:none; margin-top:20px; display:flex; flex-wrap:wrap; gap:8px}\n  .tips li{\n    position:relative; padding:4px 12px 4px 30px; border-radius:99px;\n    background:var(--ai-soft); color:var(--ai); font-size:13px; font-weight:500; line-height:1.6;\n  }\n  .tips li::before{content:\"\"; position:absolute; left:13px; top:8px; width:4px; height:8px; border-right:2px solid currentColor; border-bottom:2px solid currentColor; transform:rotate(45deg)}\n  #frame .btn{margin-top:28px}\n  .frame-note{font-size:13px; color:var(--coral-ink); min-height:1.2em; margin-top:10px}\n\n  /* ===== 設問 ===== */\n  .qcount{font-family:var(--display); font-weight:700; font-size:15px; color:var(--ink); white-space:nowrap; letter-spacing:.04em}\n  .qtop{margin-bottom:16px}\n  .bar{height:8px; background:#E9E1D4; border-radius:99px; overflow:hidden}\n  .bar > i{display:block; height:100%; width:0; background:var(--an); border-radius:99px; transition:width .45s cubic-bezier(.4,0,.2,1)}\n  .qleft{margin-top:6px; text-align:right; font-size:12px; color:var(--faint); line-height:1.6}\n  .qframe{\n    display:inline-flex; align-items:center; gap:6px; max-width:100%;\n    font-size:12.5px; color:var(--muted); line-height:1.6; margin:0 0 28px;\n    padding:6px 12px; background:var(--surface); border:1px solid var(--line); border-radius:16px;\n  }\n  .qframe:empty{display:none}\n  .qframe::before{content:\"i\"; flex:none; width:15px; height:15px; border-radius:50%; border:1.6px solid var(--ai); color:var(--ai); font-size:10px; font-weight:700; line-height:12px; text-align:center; font-family:var(--body)}\n  .qno{font-family:var(--display); font-weight:700; font-size:15px; color:var(--ai); letter-spacing:.08em; line-height:1.4}\n  .qtext{\n    font-family:var(--display); font-weight:700; font-size:clamp(19px,5.6vw,22px);\n    line-height:1.6; letter-spacing:.02em; margin:6px 0 28px; text-align:left;\n  }\n  .choices{display:flex; flex-direction:column; gap:12px}\n  .choice{\n    text-align:left; font-family:var(--body); font-size:16px; color:var(--ink); cursor:pointer;\n    background:var(--surface); border:1.5px solid var(--line); border-radius:var(--radius);\n    min-height:76px; padding:14px 18px; line-height:1.65;\n    box-shadow:0 1px 2px rgba(43,39,36,.04);\n    transition:border-color .15s, background .15s, transform .1s;\n    display:flex; gap:14px; align-items:center;\n  }\n  .choice:hover{border-color:var(--ai)}\n  .choice:active{transform:translateY(1px)}\n  .choice:focus-visible{outline:3px solid var(--an); outline-offset:2px}\n  .choice .mk{\n    flex:none; width:32px; height:32px; border-radius:50%; border:1.5px solid var(--line-strong);\n    font-family:var(--display); font-weight:700; font-size:14px; color:var(--muted);\n    display:flex; align-items:center; justify-content:center;\n  }\n  /* ひとつ戻ったときは、選んでいた答えを藍で示す */\n  .choice.is-on{border-color:var(--ai); background:var(--ai-soft)}\n  .choice.is-on .mk{border-color:var(--ai); background:var(--ai); color:#fff}\n  .qhint{text-align:center; color:var(--faint); font-size:14px; margin-top:24px; line-height:1.8}\n  .qback{\n    margin-top:20px; display:inline-flex; align-items:center; min-height:44px; padding:0 4px;\n    background:none; border:none; cursor:pointer; color:var(--muted); font-family:var(--body); font-size:14px; font-weight:500;\n  }\n  .qback:hover{color:var(--ink)}\n\n  /* 4段階：4つ全部に言葉を付ける。左＝思わない（鈍色）、右＝そう思う（藍）。採点の値は1〜4のまま */\n  .scale{background:var(--surface); border:1px solid var(--line); border-radius:20px; padding:22px 8px 18px; margin-top:4px}\n  .scale-dots{display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:4px}\n  .dot{\n    display:flex; flex-direction:column; align-items:center; gap:10px; cursor:pointer;\n    background:none; border:none; padding:0; font-family:var(--body); color:var(--muted);\n  }\n  .dot-ring{\n    display:flex; align-items:center; justify-content:center; height:56px;\n  }\n  .dot-ring::before{\n    content:\"\"; display:block; border-radius:50%; background:var(--surface);\n    transition:transform .12s, background .15s, box-shadow .15s;\n  }\n  .dot-1 .dot-ring::before{width:56px; height:56px; border:2.5px solid var(--sc-no)}\n  .dot-2 .dot-ring::before{width:44px; height:44px; border:2px solid var(--sc-no)}\n  .dot-3 .dot-ring::before{width:44px; height:44px; border:2px solid var(--sc-yes)}\n  .dot-4 .dot-ring::before{width:56px; height:56px; border:2.5px solid var(--sc-yes)}\n  .dot:hover .dot-ring::before{transform:scale(1.06)}\n  .dot-1:hover .dot-ring::before,.dot-2:hover .dot-ring::before{background:#F1ECE4}\n  .dot-3:hover .dot-ring::before,.dot-4:hover .dot-ring::before{background:var(--ai-soft)}\n  .dot:active .dot-ring::before{transform:scale(.96)}\n  .dot:focus-visible{outline:3px solid var(--an); outline-offset:3px; border-radius:12px}\n  .dot-label{font-size:12.5px; line-height:1.45; text-align:center}\n  .dot.is-on{color:var(--ai)}\n  .dot.is-on .dot-label{font-weight:700}\n  .dot.is-on .dot-ring::before{background:var(--ai); border-color:var(--ai); box-shadow:0 0 0 5px var(--ai-soft)}\n  @media (max-width:360px){\n    .dot-1 .dot-ring::before,.dot-4 .dot-ring::before{width:48px; height:48px}\n    .dot-2 .dot-ring::before,.dot-3 .dot-ring::before{width:38px; height:38px}\n    .dot-label{font-size:11.5px}\n  }\n\n  /* ===== 結果 ===== */\n  .result-accent{ --accent:var(--teal); --accent-soft:var(--teal-soft); --accent-ink:var(--teal-ink) }\n  /* 結果は1枚の箱にせず、色のついた名前のカードの下に、節ごとの面を並べる */\n  .card{background:none; border:none; box-shadow:none; overflow:visible}\n  .card-head{padding:28px 20px 24px; text-align:center; border-radius:24px; background:var(--accent-soft)}\n  .r-label{font-size:13px; font-weight:700; letter-spacing:.14em; color:var(--accent-ink); line-height:1.6}\n  .emblem-wrap{margin:14px auto 0}\n  .emblem{\n    width:88px; height:88px; border-radius:50%; margin:0 auto;\n    display:flex; align-items:center; justify-content:center;\n    background:var(--surface); color:var(--accent); box-shadow:0 6px 18px rgba(43,39,36,.08);\n  }\n  .emblem svg{width:40px; height:40px}\n  .tcatch{font-family:var(--display); font-weight:700; font-size:16px; color:var(--accent-ink); letter-spacing:.04em; margin:16px 0 0; line-height:1.6}\n  .tcatch:not(:empty)::before{content:\"「\"}\n  .tcatch:not(:empty)::after{content:\"」\"}\n  .tname{font-family:var(--display); font-weight:700; font-size:clamp(28px,8.4vw,34px); color:var(--ink); letter-spacing:.04em; margin:4px 0 0; line-height:1.4}\n  .chip{\n    display:inline-block; margin-top:12px; font-family:var(--display); font-weight:700; font-size:14px; letter-spacing:.2em;\n    color:#fff; background:var(--accent); border-radius:99px; padding:4px 12px 4px 16px; line-height:1.6;\n  }\n  /* 名前の下に、タイプを決めた3つの極（オープン・ぶつかる・引っ張る など） */\n  .rays{display:flex; justify-content:center; flex-wrap:wrap; gap:6px; margin-top:16px}\n  .ray{padding:4px 12px; border-radius:99px; background:var(--surface); color:var(--accent-ink); font-size:13px; font-weight:700; line-height:1.6}\n  .ray b,.ray i{display:none}\n  /* 節へ飛ぶチップ。長い結果の中で、読みたいところへすぐ行けるようにする */\n  .r-jump{display:flex; gap:8px; overflow-x:auto; margin:20px calc(-1 * var(--gutter)) 0; padding:0 var(--gutter) 2px; scrollbar-width:none}\n  .r-jump::-webkit-scrollbar{display:none}\n  .r-jump a{\n    flex:none; display:flex; align-items:center; height:44px; padding:0 16px; border-radius:99px;\n    background:var(--surface); border:1px solid var(--line); font-size:13px; font-weight:500; color:var(--ink); text-decoration:none; white-space:nowrap;\n  }\n  .r-jump a:hover{border-color:var(--ai); color:var(--ink)}\n  [id^=\"sec-\"]{scroll-margin-top:16px}\n  .card-body{padding:0}\n  /* 節の見出し。英字の添え書きやアイコンの面は付けない */\n  .secthead{display:flex; align-items:center; gap:12px; margin:36px 0 14px}\n  .sh-text{display:flex; flex-direction:column; gap:2px; min-width:0}\n  .sh-title{font-family:var(--display); font-size:20px; font-weight:700; color:var(--ink); letter-spacing:.02em; line-height:1.5}\n  .sh-kicker{display:none}\n  .sh-icon{\n    flex:none; width:44px; height:44px; border-radius:50%;\n    background:rgba(255,255,255,.08); color:#F6F1E9; display:flex; align-items:center; justify-content:center;\n  }\n  .sh-icon svg{width:22px; height:22px}\n  .sectlabel{font-family:var(--display); font-size:20px; font-weight:700; color:var(--ink); letter-spacing:.02em; margin:36px 0 14px; line-height:1.5}\n  .sectlabel.is-sub{font-size:17px; margin:28px 0 12px; line-height:1.6}\n  .sect-sub{font-size:14px; color:var(--muted); margin:-8px 0 14px; line-height:1.75}\n  .r-card{background:var(--surface); border:1px solid var(--line); border-radius:20px; padding:18px}\n  .axes{display:flex; flex-direction:column; background:var(--surface); border:1px solid var(--line); border-radius:20px; padding:6px 18px}\n  .axis-row{display:grid; grid-template-columns:44px 1fr; gap:12px; align-items:center; padding:14px 0; border-bottom:1px solid var(--sunken)}\n  .axis-row:last-child{border-bottom:none}\n  .axis-name{font-size:13px; color:var(--faint); font-weight:500; line-height:1.6}\n  .axis-track-wrap{position:relative; min-width:0}\n  .axis-ends{display:flex; justify-content:space-between; gap:8px; font-size:14px; color:var(--faint); line-height:1.6}\n  .axis-ends span:last-child{text-align:right}\n  .axis-ends .on{color:var(--accent-ink); font-weight:700}\n  .axis-track{position:relative; height:6px; margin-top:8px; background:var(--sunken); border-radius:99px}\n  .axis-dot{position:absolute; top:50%; width:16px; height:16px; border-radius:50%; background:var(--accent); box-shadow:0 0 0 3px var(--surface); transform:translate(-50%,-50%); transition:left .6s cubic-bezier(.4,0,.2,1)}\n  #r-spectrums .axis-ends{font-size:13px}\n  ul.aru{list-style:none; margin:0; display:flex; flex-direction:column; gap:12px; background:var(--surface); border:1px solid var(--line); border-radius:20px; padding:18px}\n  ul.aru li{position:relative; padding-left:30px; font-size:15px; line-height:1.7; color:var(--ink)}\n  ul.aru li::before{content:\"\"; position:absolute; left:0; top:3px; width:20px; height:20px; border-radius:50%; background:var(--accent-soft)}\n  ul.aru li::after{content:\"\"; position:absolute; left:7px; top:7px; width:5px; height:9px; border-right:2px solid var(--accent); border-bottom:2px solid var(--accent); transform:rotate(45deg)}\n  .row-block{margin-top:0}\n  .row-block p:not(.sectlabel){font-size:15px; line-height:1.85; color:var(--ink)}\n  .row-block .lead-in{font-weight:700; color:var(--accent-ink)}\n\n  /* トリセツ：全幅の色面に番号つきカード（身近な人に見せられる塊） */\n  .toriset-band{margin:44px calc(-1 * var(--gutter)) 0; padding:36px var(--gutter) 32px; background:var(--accent-soft); text-align:center}\n  .toriset-band .ts-title{font-family:var(--display); font-size:24px; font-weight:700; color:var(--accent-ink); letter-spacing:.04em; line-height:1.5}\n  .toriset-band .ts-lead{font-size:14px; color:var(--muted); margin:8px 0 20px; line-height:1.75}\n  .ts-card{background:var(--surface); border-radius:16px; padding:16px 18px; margin-bottom:10px; text-align:left; box-shadow:0 1px 2px rgba(43,39,36,.05)}\n  .ts-card:last-child{margin-bottom:0}\n  .ts-card .ts-l{display:flex; align-items:center; gap:8px; font-size:14px; font-weight:700; color:var(--accent-ink); line-height:1.6}\n  .ts-card .ts-l .num{\n    flex:none; width:22px; height:22px; border-radius:50%; background:var(--accent); color:#fff;\n    font-size:12px; font-weight:700; display:flex; align-items:center; justify-content:center; line-height:1;\n  }\n  .ts-card .ts-t{display:block; margin-top:8px; font-size:15px; line-height:1.75; color:var(--ink)}\n\n  /* いちばん出ている傾向 */\n  .pv{background:var(--surface); border:1px solid var(--line); border-radius:20px; overflow:hidden}\n  .pv-head{display:flex; align-items:baseline; gap:10px; flex-wrap:wrap; padding:12px 18px; background:var(--accent); color:#fff; line-height:1.6}\n  .pv-kicker{font-size:13px; font-weight:500}\n  .pv-head b{font-size:17px; font-weight:700}\n  .pv-body{padding:18px}\n  .pv-pole{font-family:var(--display); font-weight:700; font-size:18px; color:var(--accent-ink); line-height:1.6}\n  .focus-item{display:flex; gap:10px; align-items:flex-start; margin-top:10px}\n  .focus-item:first-of-type{margin-top:12px}\n  .focus-tag{flex:none; font-size:12px; font-weight:700; border-radius:6px; padding:2px 8px; line-height:1.6; white-space:nowrap}\n  .focus-tag-gift{background:var(--accent-soft); color:var(--accent-ink)}\n  .focus-tag-side{background:var(--sunken); color:var(--muted)}\n  .focus-item p{font-size:14px; line-height:1.75; color:var(--ink)}\n  .focus-grow{font-size:14px; line-height:1.75; color:var(--muted); margin-top:14px; padding-top:14px; border-top:1px solid var(--sunken)}\n\n  /* 深層：ページで唯一の暗い面。無地の夜の藍で「奥に沈む」感じを出し、そのままガイドの入口へつなぐ */\n  .deep-section{margin:48px calc(-1 * var(--gutter)) 0; padding:40px var(--gutter); background:var(--night); color:#F6F1E9}\n  .deep-section .secthead{margin:0}\n  .deep-section .sh-title{color:#F6F1E9; font-size:22px; line-height:1.4}\n  .hs-sub{font-size:13px; color:var(--night-sub); line-height:1.6}\n  .honshitsu{margin-top:24px}\n  .hs-core{font-size:16px; line-height:1.95; color:#F6F1E9}\n  .hs-cost{font-size:16px; line-height:1.95; color:#F6F1E9; margin-top:14px}\n  .hs-loop{margin-top:20px; padding:18px; border-radius:16px; background:rgba(255,255,255,.07); font-size:15px; line-height:1.85; color:#E9EEF4}\n  .compat{margin:0}\n  .compat-cta{margin-top:28px; padding-top:28px; border-top:1px solid rgba(255,255,255,.14)}\n  .compat-cta .cc-text{font-size:15px; line-height:1.85; color:var(--night-sub)}\n  .compat-cta .cc-text b{color:#fff}\n  .compat-cta .cc-text + .cc-text{margin-top:8px; font-size:14px}\n  .compat-cta .cc-label{font-family:var(--display); font-weight:700; font-size:18px; color:#fff; margin-top:14px; line-height:1.6}\n  /* 暗い面では、白抜きのボタンをいちばん強い要素にする */\n  .compat-cta .btn{margin-top:20px; background:#F6F1E9; color:var(--night); box-shadow:none}\n  .compat-cta .btn:hover{background:#fff; color:var(--night); filter:none}\n  .day-head{margin-top:24px; font-size:13px; font-weight:700; color:var(--night-sub); line-height:1.6}\n  .day-list{list-style:none; margin-top:10px; display:flex; flex-direction:column; gap:8px; font-size:14px; line-height:1.6; color:#E9EEF4}\n  .day-list li{display:flex; gap:12px}\n  .day-list li span{flex:none; width:3.4em; color:var(--night-faint)}\n  .optout-note{margin-top:12px; font-size:13px; color:var(--faint); line-height:1.6}\n  .compat-cta .optout-note{color:var(--night-faint)}\n  .cc-preview{font-size:13px; color:var(--night-sub); background:rgba(255,255,255,.06); border:1px dashed rgba(255,255,255,.25); border-radius:10px; padding:10px 12px; margin-bottom:14px; line-height:1.6}\n\n  /* 結果の下：共有・ほかのタイプ・もう一度 */\n  .r-more{margin-top:12px}\n  .r-more .sectlabel{font-size:18px; margin:0}\n  .r-more p:not(.sectlabel){margin-top:6px; font-size:14px; line-height:1.75; color:var(--muted)}\n  .r-more .btn{margin-top:16px}\n  .deep-section + .r-more{margin-top:40px}\n  .afterbar{display:flex; justify-content:center; margin-top:16px}\n  .afterbar .btn-ghost{background:none; border:none; color:var(--muted); font-weight:500; font-size:14px; min-height:44px}\n  .afterbar .btn-ghost:hover{color:var(--ink)}\n\n  /* タイプの組み立て（タイプ個別ページ）：極の3語 → タイプ */\n  .formula{display:flex; flex-direction:column; align-items:center; gap:8px; padding:18px 14px; background:var(--surface); border:1px solid var(--line); border-radius:20px}\n  .f-row{display:flex; flex-wrap:wrap; justify-content:center; align-items:center; gap:6px}\n  .f-chip{font-size:13px; font-weight:700; color:var(--accent-ink); background:var(--accent-soft); border-radius:99px; padding:5px 12px; white-space:nowrap}\n  .f-op{color:var(--faint); font-size:13px; font-weight:700}\n  .f-arrow{color:var(--accent); font-size:14px; line-height:1}\n  .f-type{font-size:17px; font-weight:700; color:var(--accent-ink)}\n  .f-type small{font-size:12px; font-weight:700; color:var(--muted); margin-left:7px; letter-spacing:.1em}\n\n  /* 宣言のフォークで使う補足の面（左の太線は使わず、淡い面で区切る） */\n  .link-note{font-size:14px; line-height:1.85; color:var(--muted); background:var(--accent-soft); border-radius:14px; padding:14px 16px; margin:14px 0 4px}\n  .link-note b{color:var(--accent-ink)}\n  .lead-cta{font-family:var(--display); font-weight:700; font-size:clamp(17px,4.6vw,19px); line-height:1.5; color:var(--accent-ink); margin-bottom:14px}\n\n  /* 検証アンケート（prototype.html の ?mode=feedback だけ）と、申込フォームの入力欄 */\n  .bridge{margin-top:30px; padding-top:30px; border-top:1px dashed var(--line)}\n  .bridge.is-bare{margin-top:0; padding-top:0; border-top:none}\n  .vq-intro{font-family:var(--display); font-weight:500; font-size:clamp(15px,3.6vw,17px); line-height:1.6; color:var(--ink); margin-bottom:22px}\n  .vq{margin-bottom:20px}\n  .vq-q{font-size:15px; font-weight:700; color:var(--ink); line-height:1.7; margin-bottom:10px}\n  .vq-opts{display:flex; flex-direction:column; gap:8px}\n  .vq-opt{\n    display:flex; align-items:center; gap:11px; cursor:pointer; min-height:48px;\n    font-size:15px; color:var(--ink); background:var(--surface);\n    border:1.5px solid var(--line); border-radius:14px; padding:11px 14px;\n    transition:border-color .15s, background .15s;\n  }\n  .vq-opt:hover{border-color:var(--ai)}\n  .vq-opt input{accent-color:var(--ai); width:16px; height:16px; flex:none; margin:0}\n  .vq-opt:has(input:checked){border-color:var(--ai); background:var(--ai-soft)}\n  .field{margin-bottom:14px}\n  .field label{display:block; font-size:14px; color:var(--muted); margin-bottom:7px; font-weight:500}\n  .field textarea, .field input, .field select{\n    width:100%; font-family:var(--body); font-size:16px; color:var(--ink); background:var(--surface);\n    border:1.5px solid var(--line-strong); border-radius:14px; padding:12px 15px; resize:vertical; line-height:1.6;\n  }\n  .field textarea:focus, .field input:focus, .field select:focus{outline:none; border-color:var(--ai); box-shadow:0 0 0 3px var(--ai-soft)}\n  .field textarea{min-height:96px}\n  .proto-note{font-size:13px; color:var(--faint); margin-top:12px; min-height:18px}\n\n  /* 幅に余裕がある画面では、全幅の帯を角丸の面にする */\n  @media (min-width:680px){\n    .toriset-band,.deep-section{margin-left:0; margin-right:0; border-radius:24px}\n    .r-jump{margin-left:0; margin-right:0; padding-left:0; padding-right:0}\n  }\n\n  /* ===== PC のトップ：左に見出しとボタン、右に2つの円。下の節は横に並べる ===== */\n  @media (min-width:960px){\n    .app:has(> #intro.active){max-width:1120px}\n    .head-pc{display:flex}\n    .head-nav .head-link{color:var(--muted)}\n    .head-nav .head-link:hover{color:var(--ink)}\n    .app-header{min-height:80px; margin-bottom:0}\n    .brand-mark{width:36px; height:26px}\n    .brand-name{font-size:21px}\n    .top-hero{display:grid; grid-template-columns:minmax(0,1fr) minmax(0,1fr); align-items:center; gap:56px; padding:40px 0 80px}\n    .top-hero .hero{margin-top:0; font-size:clamp(34px,3.6vw,46px); line-height:1.4}\n    .top-hero .lead{font-size:18px; max-width:30em; margin-top:20px}\n    .top-hero .btn{width:auto; margin-top:36px; min-height:60px; padding:14px 40px; font-size:19px}\n    .cta-note{text-align:left}\n    .top-hero-art{display:block}\n    .top-hero-art svg{display:block; width:100%; max-width:480px; height:auto; margin:0 auto}\n    .top-sec{margin-top:0; padding:72px 0}\n    /* 全幅の白い帯。横スクロールを生まないよう、影と切り抜きで面だけを広げる */\n    .top-empathy,.top-types{background:var(--surface); box-shadow:0 0 0 100vmax var(--surface); clip-path:inset(0 -100vmax)}\n    .top-h{font-size:30px; text-align:center}\n    .top-h + .top-p{text-align:center; font-size:16px; margin-top:8px}\n    .top-empathy .top-p{text-align:center; max-width:40em; margin:28px auto 0; font-size:16px}\n    .pains{flex-direction:row; gap:16px; margin-top:32px}\n    .pains li{flex:1 1 0; background:var(--bg); border:none; border-radius:16px; padding:20px 20px 20px 54px; font-size:16px}\n    .pains li::before{left:20px; top:23px}\n    .pains li::after{left:27px; top:27px}\n    .steps{flex-direction:row; gap:16px; margin-top:32px; padding:0; background:none; border:none}\n    .step{flex:1 1 0; flex-direction:column; gap:16px; padding:24px; background:var(--surface); border:1px solid var(--line); border-radius:20px}\n    .step-no{width:44px; height:44px; font-size:18px}\n    .step-t{font-size:18px; margin-top:0}\n    .step-d{font-size:15px; line-height:1.8; margin-top:6px}\n    .type-grid{gap:16px; margin-top:32px}\n    .type-tile{flex-direction:row; flex-wrap:wrap; align-items:center; gap:4px 12px; padding:20px 24px; background:var(--bg); border:none; border-radius:16px}\n    .tt-name{font-size:18px}\n    .tt-catch{display:block; flex-basis:100%; font-size:14px; color:var(--muted); line-height:1.6}\n    .top-types .more-link,.trust-list + .more-link{display:flex; justify-content:center; width:max-content; margin:20px auto 0; font-size:16px}\n    .trust-list{flex-direction:row; gap:16px; margin-top:32px; padding:0; background:none; border:none}\n    .trust-item{flex:1 1 0; flex-direction:column; gap:14px; padding:24px; background:var(--surface); border:1px solid var(--line); border-radius:20px}\n    .trust-ico{width:40px; height:40px}\n    .trust-ico svg{width:20px; height:20px}\n    .trust-t{font-size:17px; margin-top:0}\n    .trust-d{font-size:15px; line-height:1.8; margin-top:6px}\n    .top-band{margin:0 0 24px; padding:56px 24px; border-radius:28px}\n    .band-art{width:64px; height:46px; margin-bottom:16px}\n    .top-band .top-p{font-size:16px; margin-top:12px}\n    .top-band .btn{width:auto; margin-top:28px; min-height:60px; padding:14px 44px; font-size:19px}\n  }\n\n  /* ===== 読み解きガイド（アプリ内・全4章） =====\n     3日間のステップメールを、本の章立てに置き換えたもの。1章＝1画面で、メール登録なしに\n     クリックだけで読み進められる。明朝・柱・ノンブル・章扉・＊＊＊の区切りで「本」の体裁に寄せ、\n     診断結果（サンセリフのUI）と読み物レイヤーを視覚的に切り分ける。 */\n  .book{--paper:#FFFDF9; --bk-ink:#2B2724; --bk-soft:#5F574F; --bk-rule:#E3DACB; --bk-faint:#756C63}\n  .bk-top{display:flex; align-items:center; gap:10px; min-height:60px; margin-bottom:8px}\n  .bk-back{\n    display:inline-flex; align-items:center; min-height:44px; background:none; border:none; cursor:pointer; padding:0 2px;\n    font-family:var(--body); font-size:14px; font-weight:500; color:var(--muted); white-space:nowrap;\n  }\n  .bk-back:hover{color:var(--ink)}\n  .bk-rail{display:flex; gap:6px; margin-left:auto}\n  .bk-dot{\n    width:32px; height:32px; border-radius:50%; cursor:pointer; padding:0;\n    background:var(--surface); border:1px solid var(--line-strong);\n    font-family:var(--serif); font-weight:600; font-size:13px; color:var(--faint);\n    transition:border-color .15s, background .15s, color .15s;\n  }\n  .bk-dot:hover{border-color:var(--ai); color:var(--ink)}\n  .bk-dot.is-read{background:var(--ai-soft); border-color:var(--ai-soft); color:var(--ai)}\n  .bk-dot.is-on{background:var(--ai); border-color:var(--ai); color:#fff}\n  .bk-page{\n    position:relative; background:var(--paper); border:1px solid var(--bk-rule); border-radius:20px;\n    padding:clamp(22px,5vw,40px) clamp(18px,5vw,40px) 26px;\n  }\n  .bk-page.is-turn{animation:fade .4s ease both}\n  @media (prefers-reduced-motion:reduce){.bk-page.is-turn{animation:none}}\n  /* 柱（ランニングヘッド）とノンブル（ページ番号）。本らしさの芯になる2つ。 */\n  .bk-hd{\n    display:flex; justify-content:space-between; align-items:baseline; gap:12px;\n    font-family:var(--serif); font-size:11px; letter-spacing:.1em; color:var(--bk-faint);\n    border-bottom:1px solid var(--bk-rule); padding-bottom:9px; margin-bottom:8px;\n  }\n  .bk-hd span{white-space:nowrap; overflow:hidden; text-overflow:ellipsis}\n  .bk-folio{\n    font-family:var(--serif); font-size:12px; letter-spacing:.24em; color:var(--bk-faint);\n    text-align:center; margin-top:34px; padding-top:16px; border-top:1px solid var(--bk-rule);\n  }\n  /* 章扉。英字の添え書きは出さない */\n  .bk-open{text-align:center; margin:30px 0 36px}\n  .bk-kicker,.bk-cover-kicker{display:none}\n  .bk-no{font-family:var(--serif); font-weight:600; font-size:15px; letter-spacing:.3em; color:var(--ai); line-height:1.6}\n  .bk-hairline{width:32px; height:1px; background:var(--line-strong); margin:14px auto 16px}\n  .bk-title{font-family:var(--serif); font-weight:600; font-size:clamp(20px,5.6vw,24px); line-height:1.6; color:var(--bk-ink); letter-spacing:.04em}\n  .bk-sub{font-family:var(--body); font-size:14px; line-height:1.7; color:var(--bk-faint); margin-top:10px}\n  /* 扉（序章だけ・本のタイトルページ） */\n  .bk-cover{text-align:center; padding:16px 0 4px}\n  .bk-cover-title{font-family:var(--serif); font-weight:700; font-size:clamp(24px,6.6vw,32px); letter-spacing:.14em; color:var(--bk-ink); margin:0; line-height:1.5}\n  .bk-cover-for{font-family:var(--serif); font-size:15px; color:var(--bk-ink); margin-top:16px; letter-spacing:.04em}\n  .bk-cover-catch{font-family:var(--serif); font-size:13px; color:var(--bk-soft); margin-top:6px}\n  .bk-cover-frame{border:1px solid var(--bk-rule); border-width:1px 0; padding:26px 0; margin:6px 0 30px}\n  /* 本文 */\n  .bk-body{font-family:var(--serif); font-size:17px; line-height:2; letter-spacing:.02em; color:var(--bk-ink); counter-reset:bkc}\n  .bk-body p{margin-bottom:1.4em}\n  .bk-body p:last-child{margin-bottom:0}\n  /* 強調は3段階。章の中で使う数を絞って効かせる。\n       ①マーカー（.bk-kt＝文中のひと呼吸／.bk-em＝著者が【】で括った語）。杏の蛍光ペン\n       ②太ゴシック（.bk-b）… 明朝の地に混ぜる。具体的な言葉・セリフに\n       ③抜き出し（.bk-pull）／夜の藍の帯（.bk-band）… 章に1つだけ置く山 */\n  .bk-kt, .bk-em{font-weight:700; color:var(--bk-ink); background:linear-gradient(transparent 62%, var(--an-mark) 62%); padding:0 .08em}\n  .bk-kt{font-style:normal}\n  .bk-b{font-family:var(--display); font-weight:700; font-size:.93em; letter-spacing:.005em}\n  .bk-pull{\n    margin:2em 0 1.8em; padding:17px 6px; text-align:center;\n    border-top:2px solid var(--bk-ink); border-bottom:1px solid var(--bk-rule);\n    font-family:var(--serif); font-weight:600; font-size:18px; line-height:1.9; letter-spacing:.04em; color:var(--bk-ink);\n  }\n  .bk-band{\n    margin:2em 0 1.8em; padding:20px 18px; border-radius:14px; color:#F6F1E9; background:var(--night);\n    font-family:var(--serif); font-weight:600; font-size:16px; line-height:2; letter-spacing:.03em;\n  }\n  /* 暗い面ではマーカーが濁るので、杏の下線に置き換える */\n  .bk-band .bk-em, .bk-band .bk-kt{color:#fff; background:linear-gradient(transparent 86%, var(--an) 86%); padding:0}\n  /* 約束・効能の箇条書きは、淡い面で囲って一目で拾えるようにする */\n  .bk-promise{margin:0 0 1.6em; padding:18px 18px 10px; border-radius:14px; background:var(--accent-soft)}\n  .bk-promise .bk-star{margin-bottom:0}\n  .bk-promise .bk-star li{font-weight:600}\n  .bk-hit{\n    font-size:18px; font-weight:600; line-height:1.75; color:var(--bk-ink); letter-spacing:.02em;\n    padding:18px 20px; border-radius:14px; background:var(--bg); margin-bottom:1.5em !important;\n  }\n  .bk-ready{font-weight:600; letter-spacing:.04em}\n  .bk-div{text-align:center; letter-spacing:.7em; color:var(--bk-faint); font-size:11px; margin:0 0 1.9em}\n  /* 節見出し（⭐️⚠️などの記号見出しは、本の体裁では組版で表す） */\n  .bk-sec{\n    font-family:var(--serif); font-weight:600; font-size:17px; letter-spacing:.04em; color:var(--bk-ink);\n    margin:0 0 1em; padding-bottom:.5em; border-bottom:1px solid var(--bk-rule); line-height:1.7;\n  }\n  /* 環境カード・特徴カード：番号つきの枠。消耗しやすい場だけは番号なしの淡い面 */\n  .bk-card{margin-bottom:12px; padding:16px 18px; border:1px solid var(--bk-rule); border-radius:16px; counter-increment:bkc}\n  .bk-card-l{font-family:var(--serif); font-weight:600; font-size:17px; line-height:1.6; color:var(--bk-ink); margin-bottom:.4em !important; letter-spacing:.02em}\n  .bk-card-l::before{content:counter(bkc, decimal-leading-zero); font-family:var(--body); font-size:13px; font-weight:700; color:var(--an-ink); margin-right:.8em; letter-spacing:.04em}\n  .bk-card-t{font-size:15px; line-height:1.95; color:var(--bk-soft); margin-bottom:0 !important}\n  .bk-card-drain{margin-top:20px; border-color:var(--sunken); background:var(--sunken); counter-increment:none}\n  .bk-card-drain .bk-card-l::before{content:none}\n  .bk-card-drain + p, .bk-card + p{margin-top:1.6em}\n  /* コラム（トリセツ・裏モード）：本の中の別枠。見出しは色面で抜いて、面として強く見せる。 */\n  .bk-col{background:var(--surface); border:1px solid var(--bk-rule); border-radius:16px; margin:0 0 1.9em; overflow:hidden}\n  .bk-col-l{\n    font-family:var(--serif); font-weight:600; font-size:14px; letter-spacing:.2em;\n    background:var(--accent); color:#fff; text-align:center; padding:13px 14px; margin:0 !important;\n  }\n  .bk-col-in{padding:17px 18px 8px}\n  .bk-col-lead{font-size:14px; line-height:2; color:var(--bk-soft)}\n  .bk-ts{padding:11px 0; border-top:1px solid var(--bk-rule)}\n  .bk-ts-l{display:block; font-family:var(--display); font-weight:700; font-size:13px; color:var(--accent-ink); margin-bottom:4px; letter-spacing:.02em}\n  .bk-ts-t{display:block; font-size:15px; line-height:2}\n  .bk-col-warn .bk-col-l{background:var(--night)}\n  .bk-col-warn .bk-ts-l{color:var(--night)}\n  /* 箇条書き（☆・□・①②③）。原文の記号をそのまま組版に写す。 */\n  .bk-star, .bk-box, .bk-num{list-style:none; margin:0 0 1.55em; padding-left:2px}\n  .bk-star li, .bk-box li, .bk-num li{position:relative; padding-left:1.6em; line-height:2; margin-bottom:.35em; font-size:16px}\n  .bk-star li::before{content:\"☆\"; position:absolute; left:0; color:var(--an-ink)}\n  .bk-box li::before{content:\"□\"; position:absolute; left:0; color:var(--bk-faint)}\n  .bk-num li::before{content:attr(data-n); position:absolute; left:0; color:var(--an-ink)}\n  /* A/Bの対比 */\n  .bk-ab{margin:0 0 1.55em; padding:14px 16px; background:var(--bg); border-radius:14px}\n  .bk-ab p{margin-bottom:.5em !important; font-size:15px; line-height:1.95}\n  .bk-ab p:last-child{margin-bottom:0 !important}\n  .bk-ab-k{font-weight:600; color:var(--accent-ink); margin-right:.4em}\n  /* 目次 */\n  .bk-toc{margin:0 0 1.9em; padding:20px 18px; border:1px solid var(--bk-rule); border-radius:16px; background:var(--surface)}\n  .bk-toc-h{font-family:var(--serif); font-weight:600; font-size:13px; letter-spacing:.3em; text-align:center; color:var(--bk-faint); margin-bottom:1.2em !important}\n  .bk-toc-i{display:flex; gap:12px; padding:11px 0; border-top:1px solid var(--bk-rule)}\n  .bk-toc-n{flex:none; font-family:var(--serif); font-weight:600; font-size:14px; color:var(--ai); letter-spacing:.06em; padding-top:1px}\n  .bk-toc-t{font-size:14.5px; line-height:1.95; color:var(--bk-soft)}\n  /* 転（あなたという半分）：ページで一番強い段落 */\n  .bk-turn{margin:0 0 1.55em; padding:20px 18px; background:var(--bg); border-radius:14px}\n  .bk-turn p:last-child{margin-bottom:0 !important}\n  /* 次章の引き：枠に見出しラベルを食い込ませる（本の囲み記事の型） */\n  .bk-teaser{position:relative; margin:2.4em 0 1.55em; padding:22px 16px 8px; border:1px solid var(--bk-rule); border-radius:16px; background:var(--surface)}\n  .bk-teaser-l{\n    position:absolute; top:-10px; left:14px; padding:0 9px; background:var(--paper);\n    font-family:var(--serif); font-weight:600; font-size:12px; letter-spacing:.24em; color:var(--ai);\n  }\n  .bk-teaser p:last-child{margin-bottom:0 !important}\n  /* 図解：テンポを変えるための挿図。外部素材は使わず、自作のインラインSVGで組む。 */\n  .bk-fig{margin:0 0 1.9em; padding:20px 15px 16px; border:1px solid var(--bk-rule); border-radius:16px; background:var(--surface)}\n  .bk-fig-cap{\n    font-family:var(--serif); font-weight:600; font-size:12px; letter-spacing:.2em; color:var(--bk-faint);\n    text-align:center; margin-bottom:16px !important;\n  }\n  .bk-fig-step{display:flex; align-items:center; gap:13px; padding:11px 13px; border:1px solid var(--bk-rule); border-radius:12px; background:var(--paper)}\n  .bk-fig-step.is-goal{border-color:var(--accent); background:var(--accent-soft)}\n  .bk-fig-ico{\n    flex:none; width:40px; height:40px; border-radius:50%; background:var(--accent-soft); color:var(--accent-ink);\n    display:flex; align-items:center; justify-content:center;\n  }\n  .bk-fig-step.is-goal .bk-fig-ico{background:var(--accent); color:#fff}\n  .bk-fig-ico svg{width:23px; height:23px}\n  .bk-fig-t{font-family:var(--serif); font-weight:600; font-size:15px; line-height:1.7; color:var(--bk-ink)}\n  .bk-fig-ar{text-align:center; color:var(--accent); font-size:12px; line-height:1; padding:8px 0}\n  /* 図の中の「自分では見えない」区間。破線の囲みにラベルを食い込ませて、範囲そのものを見せる。 */\n  .bk-blind{position:relative; padding:20px 11px 11px; border:1px dashed var(--line-strong); border-radius:12px; background:var(--bg)}\n  .bk-blind-l{\n    position:absolute; top:-10px; left:12px; padding:0 8px; background:var(--surface);\n    font-family:var(--display); font-weight:700; font-size:11px; letter-spacing:.16em; color:var(--bk-faint);\n  }\n  .bk-fig-step.is-blind{border-style:dashed; background:transparent}\n  .bk-fig-step.is-blind .bk-fig-ico{background:var(--sunken); color:var(--bk-faint)}\n  .bk-fig-step.is-blind .bk-fig-t{color:var(--bk-soft)}\n  .bk-fig-note{font-size:14px !important; line-height:1.95; color:var(--bk-soft); text-align:center; margin:16px 0 0 !important}\n  /* 終章のCTA：本の中で唯一の藍の面。読み物から申し込みへ温度を上げる。 */\n  .bk-cta{margin-top:30px; padding:26px 20px 22px; border-radius:20px; color:#fff; background:var(--ai)}\n  .bk-cta-kicker{font-family:var(--body); font-size:13px; font-weight:700; letter-spacing:.1em; color:rgba(255,255,255,.85); margin-bottom:10px}\n  .bk-cta-title{font-family:var(--serif); font-weight:600; font-size:clamp(18px,4.8vw,20px); line-height:1.75; margin-bottom:14px}\n  .bk-cta-text{font-family:var(--serif); font-size:15px; line-height:2; color:rgba(255,255,255,.9); margin-bottom:16px}\n  .bk-cta .field label{color:rgba(255,255,255,.85)}\n  .bk-cta .field textarea, .bk-cta .field input, .bk-cta .field select{color:#fff; background:rgba(255,255,255,.1); border-color:rgba(255,255,255,.3)}\n  .bk-cta .field textarea::placeholder{color:rgba(255,255,255,.5)}\n  .bk-cta .field select option{color:var(--ink); background:#fff}\n  .bk-cta .field textarea:focus, .bk-cta .field select:focus{border-color:rgba(255,255,255,.7); box-shadow:none}\n  .bk-apply{\n    display:flex; align-items:center; justify-content:center; width:100%; min-height:58px; text-align:center; text-decoration:none;\n    font-family:var(--body); font-size:17px; font-weight:700; letter-spacing:.04em;\n    background:#F6F1E9; color:var(--ai); border:none; border-radius:99px; padding:14px 30px; cursor:pointer;\n  }\n  .bk-apply:hover{background:#fff; color:var(--ai)}\n  .bk-apply.is-off{background:rgba(255,255,255,.22); color:rgba(255,255,255,.7); cursor:default; pointer-events:none}\n  .bk-cta-note{font-size:13px; color:rgba(255,255,255,.8); margin-top:10px; line-height:1.7}\n  /* 自己紹介（申込フォームの後ろ）と、そのあとの2度目のCTA */\n  .bk-bio{margin-top:26px}\n  .bk-bio p{margin-bottom:1.4em}\n  .bk-bio p:last-child{margin-bottom:0}\n  .bk-cta-2{margin-top:24px; padding:22px 20px}\n  .bk-cta-text2{\n    font-family:var(--serif); font-weight:600; font-size:16px; line-height:1.9;\n    color:#fff; margin-bottom:16px; text-align:center;\n  }\n  /* 章の移動：画面の下に固定したバー。左に前の章、右に次の章 */\n  .bk-nav{\n    position:sticky; bottom:0; z-index:5;\n    display:flex; flex-direction:row-reverse; align-items:center; justify-content:space-between; gap:12px;\n    margin:20px calc(-1 * var(--gutter)) 0; padding:12px var(--gutter) calc(12px + env(safe-area-inset-bottom));\n    background:rgba(255,253,249,.96); border-top:1px solid var(--line);\n  }\n  .bk-next{\n    display:inline-flex; align-items:center; gap:6px; min-height:48px; padding:0 18px 0 22px; cursor:pointer;\n    background:var(--chrome); color:#fff; border:none; border-radius:99px;\n    font-family:var(--body); font-size:15px; font-weight:700; transition:background .2s, transform .1s;\n  }\n  .bk-next:hover{background:var(--chrome-hover)}\n  .bk-next:active{transform:translateY(1px)}\n  .bk-next-l{display:none}\n  .bk-next-t{line-height:1.4}\n  .bk-next-a{display:none}\n  .bk-next::after{content:\"\"; width:7px; height:7px; border-top:2px solid currentColor; border-right:2px solid currentColor; transform:rotate(45deg); margin-left:2px}\n  .bk-prev{\n    display:inline-flex; align-items:center; gap:6px; min-height:44px; padding:0 16px 0 14px; cursor:pointer;\n    background:var(--surface); border:1.5px solid var(--line-strong); border-radius:99px;\n    font-family:var(--body); font-size:14px; font-weight:700; color:var(--ink);\n  }\n  .bk-prev::before{content:\"\"; width:7px; height:7px; border-bottom:2px solid currentColor; border-left:2px solid currentColor; transform:rotate(45deg); margin-right:2px}\n  .bk-prev:hover{border-color:var(--ai)}\n  @media (min-width:680px){ .bk-nav{margin-left:0; margin-right:0; border-radius:16px 16px 0 0} }\n  .bk-endbar{display:flex; gap:12px; flex-wrap:wrap; justify-content:center; margin-top:26px}\n\n  /* ===== 全8タイプ一覧（アプリの /types と /types/{code}）=====\n     本音の極（O／G）でまとめて並べる。色を付けるのは本音の極だけで、衝突・重心は無地にする。 */\n  .tl-group{display:flex; align-items:center; gap:8px; margin:28px 0 12px; font-family:var(--display); font-size:16px; font-weight:700; line-height:1.6}\n  .tl-group::before{content:\"\"; width:10px; height:10px; border-radius:50%; background:var(--coral); flex:none}\n  .tl-group.is-guard::before{background:var(--teal)}\n  .tl-list{list-style:none; display:flex; flex-direction:column; gap:10px}\n  .tl-card{\n    display:flex; align-items:center; gap:14px; padding:14px 16px;\n    background:var(--surface); border:1px solid var(--line); border-radius:16px; color:var(--ink); text-decoration:none;\n  }\n  .tl-card:hover{color:var(--ink); border-color:var(--line-strong)}\n  .tl-card[aria-current]{background:var(--accent-soft); border-color:transparent}\n  .tl-emblem{flex:none; width:44px; height:44px; border-radius:50%; background:var(--coral-soft); color:var(--coral); display:flex; align-items:center; justify-content:center}\n  .tl-emblem svg{width:22px; height:22px}\n  .tl-main{flex:1; min-width:0}\n  .tl-top{display:flex; align-items:center; gap:8px}\n  .tl-code{flex:none; padding:1px 7px; border-radius:99px; background:var(--coral); color:#fff; font-size:11px; font-weight:700; letter-spacing:.1em; line-height:1.6}\n  .tl-name{font-family:var(--display); font-weight:700; font-size:16px; line-height:1.5}\n  .tl-catch{display:block; margin-top:2px; font-size:13px; color:var(--muted); line-height:1.6}\n  .tl-chev{flex:none; width:8px; height:8px; border-top:2px solid var(--sc-no); border-right:2px solid var(--sc-no); transform:rotate(45deg); margin-right:4px}\n  .tl-card.is-guard .tl-emblem{background:var(--teal-soft); color:var(--teal)}\n  .tl-card.is-guard .tl-code{background:var(--teal)}\n  .ax-cards{display:flex; flex-direction:column; gap:10px; margin-top:16px}\n  .ax-card{padding:18px; background:var(--surface); border:1px solid var(--line); border-radius:20px}\n  .ax-name{font-family:var(--display); font-size:17px; font-weight:700; line-height:1.5}\n  .ax-desc{margin-top:4px; font-size:14px; line-height:1.75; color:var(--muted)}\n  .ax-poles{margin-top:12px; display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:8px}\n  .ax-pole{padding:8px 10px; border-radius:12px; background:var(--sunken); color:var(--ink); font-size:14px; font-weight:700; text-align:center; line-height:1.5}\n  .ax-pole.is-open{background:var(--coral-soft); color:var(--coral-ink)}\n  .ax-pole.is-guard{background:var(--teal-soft); color:var(--teal-ink)}\n  @media (min-width:680px){\n    .tl-wide{display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:10px}\n  }\n";

/** 全8タイプ一覧の索引リンク。all-types.html から。 */
export const INDEX_CSS = "  .ix{display:flex; align-items:center; gap:8px; text-decoration:none; color:var(--ink);\n    border:1px solid var(--line); border-radius:10px; padding:8px 10px; background:var(--surface); font-size:12.5px}\n  .ix .c{font-family:var(--display); font-weight:700; font-size:10.5px; letter-spacing:.14em; color:#fff; border-radius:6px; padding:2px 7px}\n  .ix.open .c{background:var(--coral)} .ix.guard .c{background:var(--teal)}";
